import * as T from 'three';
import {FaceWarp} from './face-warp.js';
export function installFacePreview({scene,camera,controls,meshes,manifest,state,rays,assetVersion}){
 const panel=document.createElement('details');panel.open=true;panel.innerHTML=`<summary>大鏡を使った顔への投影</summary><p>プロジェクタ → 小鏡 → 大鏡 → 顔。顔を透過・拡散するスクリーンとして外側から映像を表示します。</p><label><input id="face-projection" type="checkbox"> 顔への投影を表示</label><br><select id="face-projection-source"><option value="mapped">顔全体に合わせる映像変換（プレビュー）</option><option value="raw">入力映像をそのまま投影</option></select><br><button id="face-projection-front">顔を正面から見る</button><button id="face-projection-whole">試作機全体を見る</button><p id="face-projection-status">有効にすると投影データを読み込みます。</p><p>幾何学的な投影と部品の遮蔽を頂点で近似しています。明るさ・ピント・樹脂の実際の透過率は未再現です。映像変換はプレビュー内だけに適用します。</p>`;
 document.querySelector('aside').prepend(panel);const $=id=>document.getElementById(id),face=meshes.face,originalMaterial=face.material;let enabled=false,ready=false,busy=false,timer,warp,material,texture;const raw=document.createElement('canvas');raw.width=1280;raw.height=720;const rc=raw.getContext('2d'),canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;const ctx=canvas.getContext('2d');
 function front(){camera.fov=38;camera.updateProjectionMatrix();camera.position.set(550,0,170);controls.target.set(0,0,155);controls.update()}
 function whole(){camera.fov=38;camera.updateProjectionMatrix();camera.position.set(760,-860,470);controls.target.set(-65,0,70);controls.update()}
 async function prepare(){if(ready)return;const base='assets/projection-prototype/unified-head-v5/face-preview/';const [meta,uvb,litb]=await Promise.all([fetch(base+'metadata.json?v='+assetVersion,{cache:'no-store'}).then(r=>r.json()),fetch(base+'uv.bin?v='+assetVersion,{cache:'no-store'}).then(r=>r.arrayBuffer()),fetch(base+'lit.bin?v='+assetVersion,{cache:'no-store'}).then(r=>r.arrayBuffer())]);const g=face.geometry;if(meta.vertices!==g.attributes.position.count||JSON.stringify(meta.layout)!==JSON.stringify(state))throw Error('モデルと投影データが一致しません。ページを再読み込みしてください（モデル '+g.attributes.position.count+' / 投影 '+meta.vertices+' 頂点）。');const uv=new Float32Array(uvb),lit=new Float32Array(litb);g.setAttribute('projectionUV',new T.BufferAttribute(uv,2));g.setAttribute('illuminated',new T.BufferAttribute(lit,1));const ix=[];const pos=g.attributes.position;for(let i=0;i<pos.count;i+=3){const a=new T.Vector3().fromBufferAttribute(pos,i),b=new T.Vector3().fromBufferAttribute(pos,i+1),c=new T.Vector3().fromBufferAttribute(pos,i+2);if(b.sub(a).cross(c.sub(a)).x>0)ix.push(i,i+1,i+2);}g.userData.outerIndices=new Uint32Array(ix);warp=new FaceWarp();warp.update(g,uv,lit);texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.minFilter=T.LinearFilter;texture.generateMipmaps=false;material=new T.ShaderMaterial({side:T.DoubleSide,uniforms:{map:{value:texture}},vertexShader:'attribute vec2 projectionUV;attribute float illuminated;varying vec2 vUV;varying float vLight;void main(){vUV=projectionUV;vLight=illuminated;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'uniform sampler2D map;varying vec2 vUV;varying float vLight;void main(){vec3 color=texture2D(map,clamp(vUV,0.,1.)).rgb;gl_FragColor=vec4(vec3(.025)+color*smoothstep(.35,.75,vLight),1.);\n#include <colorspace_fragment>\n}'});ready=true;window.prototypeFacePreview={ready:true,enabled,vertices:meta.vertices,unblockedVertices:meta.unblockedVertices,uniqueVertices:meta.uniqueVertices};}
 async function frame(){if(!enabled||busy||!ready)return;busy=true;try{let source;try{const r=await fetch('/api/frame?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error();source=await createImageBitmap(await r.blob());}catch{source=new Image();source.src='assets/small-mirror-study/open-campus-frame.jpg';await source.decode();}if(!enabled){source.close?.();return;}rc.drawImage(source,0,0,1280,720);source.close?.();ctx.clearRect(0,0,1280,720);ctx.drawImage($('face-projection-source').value==='mapped'?warp.paint(raw,state.source):raw,0,0,1280,720);texture.needsUpdate=true;$('face-projection-status').textContent='顔の外側へ映像を表示中。暗い部分は投影範囲外または遮蔽の近似結果です。';}catch(e){$('face-projection-status').textContent='映像を読み込めません：'+e.message;}finally{busy=false;}}
 async function toggle(){enabled=$('face-projection').checked;if(!enabled){clearInterval(timer);face.material=originalMaterial;$('face-projection-status').textContent='顔への投影表示は停止中です。';if(window.prototypeFacePreview)window.prototypeFacePreview.enabled=false;return;}if($('ceiling-on').checked){$('ceiling-on').checked=false;$('ceiling-on').dispatchEvent(new Event('change'));}for(const p of manifest.parts){const m=meshes[p.name];if(m&&!p.template){m.visible=true;m.position.set(0,0,0);}}meshes.head.visible=true;for(const id of ['head','face','hardware'])$(id).checked=true;$('explode-face').checked=false;rays.visible=true;front();$('face-projection-status').textContent='投影と遮蔽データを読み込み中…';try{await prepare();if(!enabled)return;face.material=material;window.prototypeFacePreview.enabled=true;await frame();clearInterval(timer);timer=setInterval(frame,500);}catch(e){$('face-projection-status').textContent=e.message;}}
 $('face-projection').onchange=toggle;$('face-projection-front').onclick=front;$('face-projection-whole').onclick=whole;$('face-projection-source').onchange=frame;$('ceiling-on').addEventListener('change',()=>{if($('ceiling-on').checked&&enabled){$('face-projection').checked=false;toggle();}});addEventListener('pagehide',()=>clearInterval(timer));if(new URLSearchParams(location.search).has('faceProjection')){$('face-projection').checked=true;toggle();}
}
